import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.Dsf4_p3t.js";const g=JSON.parse('{"title":"手写汇编内核","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/native-asm.md","filePath":"zh/guide/native-asm.md","lastUpdated":1791194760000}'),s={name:"zh/guide/native-asm.md"};function i(c,t,r,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="手写汇编内核" tabindex="-1">手写汇编内核 <a class="header-anchor" href="#手写汇编内核" aria-label="Permalink to &quot;手写汇编内核&quot;">​</a></h1><p>NeoFlux 把少量性能关键的内核以手写汇编的形式放在 <code>neoflux/src/native/asm/</code>，通过<strong>纯 C ABI</strong>调用，绝不在 C++ 源码里写内嵌 asm。 本页说明这些内核为什么存在、树的哪些层允许碰 SIMD、每个内核必须遵守的契约， 以及新增一个内核的清单。</p><p>多数贡献者不需要读这一页。内核对外的唯一入口是 <code>neoflux::native::PremultiplyRgba8()</code>：它是可移植的，在所有平台都有标量回退， 框架其余部分调用的就是它。</p><h2 id="为什么是汇编而不是-intrinsic" tabindex="-1">为什么是汇编而不是 intrinsic <a class="header-anchor" href="#为什么是汇编而不是-intrinsic" aria-label="Permalink to &quot;为什么是汇编而不是 intrinsic&quot;">​</a></h2><p>intrinsic 是一次<strong>请求</strong>，不是一条指令。编译器自行决定指令序列、寄存器分配 和调度，而且每个编译器决定得都不一样。对一个必须在 GCC / Clang / MSVC / AppleClang 上逐字节一致的内核来说，这种自由度本身就是 bug：</p><table tabindex="0"><thead><tr><th></th><th>Intrinsic</th><th>手写汇编</th></tr></thead><tbody><tr><td>指令选择</td><td>各编译器自行决定</td><td>由源文件固定</td></tr><tr><td>寄存器分配</td><td>各编译器自行决定</td><td>由源文件固定</td></tr><tr><td>跨编译器输出</td><td>相近，但不保证一致</td><td>构造上即逐字节一致</td></tr><tr><td>换新工具链</td><td>可能静默改变代码生成</td><td>同样的代码，或明确的链接错误</td></tr><tr><td>读懂内核</td><td>需要了解编译器行为</td><td>读一个文件即可</td></tr></tbody></table><p>因此，当内核的 <strong>ABI 行为</strong>或<strong>数值结果</strong>不能依赖编译器的选择时，汇编才是 正确的工具。反过来，如果编译器已有稳定 intrinsic、且结果不依赖具体指令选择， 那就该用 intrinsic 并落到 platform 层（见 <a href="#什么时候不该写汇编">什么时候不该写汇编</a>）。</p><div class="tip custom-block"><p class="custom-block-title">汇编不是为了走性能捷径</p><p>premultiply 内核写成汇编的理由是<strong>确定性</strong>，不是速度。编译器很乐意帮你把标量 循环向量化；它不会承诺的是：明天、或者换个编译器，仍然选出同样的指令和同样的 寄存器。</p></div><h2 id="目录与分层策略" tabindex="-1">目录与分层策略 <a class="header-anchor" href="#目录与分层策略" aria-label="Permalink to &quot;目录与分层策略&quot;">​</a></h2><p>SIMD 不允许泄漏到调用它的层。业务代码、渲染管线、调度层调用 <code>PremultiplyRgba8()</code>，它们<strong>不需要</strong>知道 SSE2 或 NEON 的存在。</p><table tabindex="0"><thead><tr><th>目录</th><th>Intrinsic 头</th><th>内嵌 asm</th><th>调用 C ABI 内核</th></tr></thead><tbody><tr><td><code>src/apps/</code>、<code>src/widgets/</code>、<code>src/core/</code>、业务代码</td><td>禁止</td><td>禁止</td><td>否（用 <code>PremultiplyRgba8()</code>）</td></tr><tr><td>渲染管线、调度层</td><td>禁止</td><td>禁止</td><td>否（用 <code>PremultiplyRgba8()</code>）</td></tr><tr><td><code>src/native/</code>（dispatch / 特性探测 / platform）</td><td>允许</td><td>禁止</td><td>是，它就是 dispatch 层</td></tr><tr><td><code>src/native/asm/</code></td><td>不适用（它本身就是汇编）</td><td>唯一允许放 <code>.S</code> 的地方</td><td>不适用</td></tr><tr><td><code>verify/</code>、<code>tests/</code></td><td>允许，且不进发布产物</td><td>禁止</td><td>是，仅用于对照校验</td></tr></tbody></table><p>这些规则由 CI 的 <code>policy</code> job 强制执行：</p><ul><li><strong>C++ 中禁止内嵌 asm</strong> —— 所有 <code>.h</code>/<code>.cpp</code> 中出现 <code>__asm__</code>、<code>__asm</code>、 <code>asm volatile</code> 即失败。手写例程一律放在 <code>src/native/asm/</code>，通过 <code>extern &quot;C&quot;</code> 声明接入。这正是内核得以独立于任何编译器的内嵌 asm 模型的原因。</li><li><strong><code>src/native/</code>、<code>tests/</code>、<code>verify/</code> 之外禁止 intrinsic 头</strong> —— <code>&lt;immintrin.h&gt;</code>、<code>&lt;emmintrin.h&gt;</code>、<code>&lt;arm_neon.h&gt;</code>、<code>&lt;intrin.h&gt;</code> 等一律拒绝。 匹配前会先剥掉行注释，因为规则本身就写在必然要拼出这些被禁 token 的注释里。</li><li><strong>汇编 ABI 契约</strong> —— 每个 <code>.S</code> 必须导出一个 <code>asm_symbols.h</code> 确实声明过的 <code>neoflux_</code> 前缀符号，并遵守下面的寄存器纪律。</li></ul><div class="warning custom-block"><p class="custom-block-title">测试里用 intrinsic 是刻意的</p><p><code>verify/test_native_simd.cpp</code> 会包含 <code>&lt;emmintrin.h&gt;</code>。如果只拿 dispatch 层自己 的标量内核做对照，那么共享算术里的 bug 会自己骗过自己，所以测试还要比对 <strong>第二个独立的 intrinsic oracle</strong>。该文件只编译成一次性二进制，从不发布。</p></div><h3 id="什么时候不该写汇编" tabindex="-1">什么时候不该写汇编 <a class="header-anchor" href="#什么时候不该写汇编" aria-label="Permalink to &quot;什么时候不该写汇编&quot;">​</a></h3><p>如果某个操作编译器已有稳定 intrinsic、且结果不依赖具体指令选择，就不要写汇编： 用 intrinsic 实现，放在 platform 层（<code>src/native/</code>），不要扩散出去。仓库里就有 三个现成的例子：</p><ul><li><strong>cpuid</strong> —— <code>__cpuid</code> / <code>__cpuidex</code>。</li><li><strong>预取</strong> —— <code>__builtin_prefetch</code> / <code>_mm_prefetch</code>。</li><li><strong>MSVC 上的 xgetbv</strong> —— <code>_xgetbv</code> intrinsic；正因如此，<code>asm/xgetbv.S</code> 只在 非 MSVC 的 x86-64 构建里被链接。</li></ul><h2 id="已有内核" tabindex="-1">已有内核 <a class="header-anchor" href="#已有内核" aria-label="Permalink to &quot;已有内核&quot;">​</a></h2><table tabindex="0"><thead><tr><th>符号</th><th>文件</th><th>指令集</th><th>每次像素数</th><th>架构基线？</th></tr></thead><tbody><tr><td><code>neoflux_premultiply_rgba8</code></td><td><code>asm/premultiply_rgba_x86_64.S</code></td><td>SSE2</td><td>4</td><td>是（x86-64）</td></tr><tr><td><code>neoflux_premultiply_rgba8</code></td><td><code>asm/premultiply_rgba_aarch64.S</code></td><td>NEON / ASIMD</td><td>8</td><td>是（AArch64）</td></tr><tr><td><code>neoflux_read_xcr0</code></td><td><code>asm/xgetbv.S</code></td><td>x86-64（非 SIMD）</td><td>不适用</td><td>不适用</td></tr></tbody></table><p>两个 premultiply 文件定义的是<strong>同一个</strong>符号名，这是刻意的：CMake 对每个目标 只链接其中一个，于是 <code>src/native/simd_kernels.cpp</code> 里的 dispatch 层可以完全 不知道架构，也永远不必说出某个指令集的名字。</p><h3 id="为什么没有运行时-cpu-探测" tabindex="-1">为什么没有运行时 CPU 探测 <a class="header-anchor" href="#为什么没有运行时-cpu-探测" aria-label="Permalink to &quot;为什么没有运行时 CPU 探测&quot;">​</a></h3><p><code>src/native/native_tuning.h</code> 里的 <code>DetectCpuFeatures()</code> 会报告 <code>sse42</code>、 <code>avx2</code>、<code>neon</code>、<code>neon_fp16</code>。一个需要 AVX2 或 SVE2 的内核必须在运行时查它， 因为那些是可选扩展，而且操作系统也可能拒绝使能（x86 上是 XCR0，也就是 <code>asm/xgetbv.S</code> 读的那个；AArch64 上是 <code>HWCAP</code>）。</p><p>已发布的两个内核不同：<strong>SSE2 是 x86-64 的架构基线</strong>，<strong>Advanced SIMD（NEON） 是 AArch64 的架构基线</strong>——这些目标的每一种实现都保证它们。运行时探测没有任何 可决定的东西，只会给热路径多加一个分支，所以选择纯粹发生在编译期，按目标架构 决定。</p><h2 id="内核契约" tabindex="-1">内核契约 <a class="header-anchor" href="#内核契约" aria-label="Permalink to &quot;内核契约&quot;">​</a></h2><p><code>src/native/asm/</code> 下每个内核都遵守同一份契约：</p><ol><li><strong>固定的 N</strong> —— SSE2 下 4 个像素，NEON 下 8 个，并在文件头注明。</li><li><strong>返回已转换的像素数</strong> —— <code>floor(pixels / N) * N</code>。</li><li><strong>绝不碰尾部</strong> —— 超出返回数量的像素完全不动，调用方可以用标量内核补齐， 不会有任何像素被转换两次。</li><li><strong>允许别名</strong> —— <code>dst</code> 可以等于 <code>src</code>。</li><li><strong>没有错误分支</strong> —— 空指针与零长度的守卫属于 dispatch 封装 （<code>PremultiplyRgba8()</code>），不属于汇编。</li></ol><p>公式（通道 <code>c</code> 取 <code>{R, G, B}</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dst[c] = (src[c] * src[a] + 127) / 255</span></span>
<span class="line"><span>dst[a] = src[a]</span></span></code></pre></div><h3 id="除以-255-是精确的" tabindex="-1">除以 255 是精确的 <a class="header-anchor" href="#除以-255-是精确的" aria-label="Permalink to &quot;除以 255 是精确的&quot;">​</a></h3><p>这里的除法不是移位近似。令 <code>t = channel * alpha + 127</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(t + (t &gt;&gt; 8)) &gt;&gt; 8   ==   floor(t / 255)   对 [0, 65152] 内所有 t 成立</span></span></code></pre></div><p><code>channel * alpha</code> 最大 65025，所以 <code>t</code> 最大 65152，且所有中间值都不超过 65406——16 位通道永不溢出，不需要扩宽到 32 位。不要把它&quot;简化&quot;成只右移 8 位： 那会对每一个被舍入项推过边界的值都差一。</p><h2 id="abi-与寄存器纪律" tabindex="-1">ABI 与寄存器纪律 <a class="header-anchor" href="#abi-与寄存器纪律" aria-label="Permalink to &quot;ABI 与寄存器纪律&quot;">​</a></h2><p>这是最容易踩、也最难发现的坑。一个破坏了被调用方保存寄存器的内核，在那个寄存器 恰好是调用方保存的 ABI 上能通过全部测试，而在另一个 ABI 上静默毁掉调用方。</p><table tabindex="0"><thead><tr><th>目标</th><th>被调用方保存的向量寄存器</th><th>内核可用的寄存器</th></tr></thead><tbody><tr><td>x86-64（SysV AMD64 与 Win64）</td><td>Win64：<code>xmm6</code>-<code>xmm15</code>；SysV：无</td><td>只能用 <code>xmm0</code>-<code>xmm5</code></td></tr><tr><td>AArch64（AAPCS64）</td><td><code>v8</code>-<code>v15</code> 的低 64 位</td><td><code>v0</code>-<code>v7</code> 与 <code>v16</code>-<code>v31</code></td></tr></tbody></table><p>两个 64 位 x86 ABI 的交集是 <code>xmm0</code>-<code>xmm5</code>，所以 x86-64 内核把自己严格限制在 这六个之内。碰 <code>xmm6</code> 及以上，正是&quot;手写内核在 Linux 上通过、在 Windows 上悄悄 毁掉调用方状态&quot;的经典成因。</p><p>已发布的 AArch64 内核用了 <code>v0</code>-<code>v7</code> 加 <code>v16</code>、<code>v17</code>。CI 会拒绝任何 <code>*_aarch64.S</code> 中出现 <code>v8</code>-<code>v15</code>。</p><p>内核还依赖以下 ABI 事实：</p><ul><li><strong>整型参数</strong>在两个 64 位 x86 ABI 上不同（SysV 用 <code>RDI</code>/<code>RSI</code>/<code>RDX</code>，Win64 用 <code>RCX</code>/<code>RDX</code>/<code>R8</code>）。用宏隐藏差异，一份指令流服务两者。</li><li><strong>只用调用方保存的通用寄存器</strong> —— x86-64 内核用 <code>R10</code> 做循环计数、<code>RAX</code> 存 返回值；AArch64 内核用 <code>X3</code> 和 <code>X9</code>。没有任何东西需要保存与恢复。</li><li><strong>Apple 符号修饰</strong> —— Mach-O 会给 C 符号加前导下划线，用 <code>SYMBOL_NAME()</code> 宏隐藏。这也是这些文件使用大写 <code>.S</code>（走 C 预处理器）的原因。</li><li><strong>不建 <code>.rodata</code></strong> —— 常量用 ALU 指令现场构造（<code>pcmpeqd</code> / <code>psrlw</code> / <code>psllq</code> / <code>movi</code>），保持位置无关。</li></ul><h2 id="如何新增一个内核" tabindex="-1">如何新增一个内核 <a class="header-anchor" href="#如何新增一个内核" aria-label="Permalink to &quot;如何新增一个内核&quot;">​</a></h2><p>按顺序走完这份清单。第 2 至 6 步各有一道 CI 门禁，所以漏掉任何一步都是一次 红色构建，而不是一次静默的遗漏。</p><ol><li><strong>先判断该不该写成汇编。</strong> 如果已有稳定 intrinsic、且结果不依赖指令选择， 就此打住，改用 intrinsic 放到 platform 层。</li><li><strong>在 <code>neoflux/src/native/asm/</code> 写 <code>.S</code></strong> —— 一个文件一个函数，符号带 <code>neoflux_</code> 前缀，文件头写清契约与所遵循的 ABI，每条指令后都有注释，并遵守 上面的寄存器纪律。循环沿用现有内核的形状：固定组大小、返回数量、绝不碰尾部。</li><li><strong>在 <code>asm/asm_symbols.h</code> 里登记</strong> <code>extern &quot;C&quot;</code> 声明，用 <code>NEOFLUX_NATIVE_ASM_*</code> 宏保护。不要在调用点自己写 <code>extern &quot;C&quot;</code>。CI 会检查 每个 <code>.S</code> 都导出了本头声明过的符号，所以未登记的文件不可能&quot;悄悄从未被链接&quot;。</li><li><strong>在 <code>neoflux/CMakeLists.txt</code> 里按目标架构选用</strong> —— 显式 <code>target_sources(...)</code> 加对应的私有 <code>target_compile_definitions(...)</code>，没有 glob。MSVC 除外：它汇编的是 MASM（<code>.asm</code>）而不是 GAS（<code>.S</code>），发布一份这里 无法验证的 MASM 翻译比直接回退更糟。</li><li><strong>在 <code>src/native/simd_kernels.{h,cpp}</code> 里接上 dispatch</strong> —— 新增 <code>SimdLevel</code> 枚举项、组大小、编译期分派，以及标量尾部路径。对 C ABI 符号的 调用要用 <code>#if defined(...)</code> 保护，<strong>不要</strong>用 <code>if (group != 0)</code>：常量为假的 运行时条件仍然会留下一个链接期引用，而没有哪个编译器承诺会把它擦掉。</li><li><strong>若指令集不是架构基线</strong>，用 <code>DetectCpuFeatures()</code>（以及 OS 可能拒绝时的 XCR0 / HWCAP）做运行时门禁，并保留可达的标量路径。已发布的两个内核不需要 这些。</li><li><strong>给 <code>verify/test_native_simd.cpp</code> 加对照用例</strong>，并把编译命令补进 <code>verify/README.md</code>。</li><li><strong>更新文档</strong> —— 本页，以及（如果内核对用户可见）相应的指南页。</li></ol><div class="warning custom-block"><p class="custom-block-title">两个独立开关就是两次不一致的机会</p><p>CMake 为每个内核只定义一个架构宏，<code>NEOFLUX_NATIVE_ASM_PREMULTIPLY</code> 这个总开关 是在 <code>asm_symbols.h</code> 里推导出来的。分开定义两者会让它们有机会互相矛盾，而这里 的矛盾表现为链接错误，不是回退。</p></div><h2 id="构建配置" tabindex="-1">构建配置 <a class="header-anchor" href="#构建配置" aria-label="Permalink to &quot;构建配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>生效的内核</th><th><code>ActiveSimdLevel()</code></th></tr></thead><tbody><tr><td>x86-64 上的 GCC / Clang / AppleClang</td><td><code>premultiply_rgba_x86_64.S</code></td><td><code>kSse2</code></td></tr><tr><td>AArch64 上的 GCC / Clang / AppleClang</td><td><code>premultiply_rgba_aarch64.S</code></td><td><code>kNeon</code></td></tr><tr><td>MSVC（任何架构）</td><td>无，纯标量</td><td><code>kScalar</code></td></tr><tr><td>其他处理器</td><td>无，纯标量</td><td><code>kScalar</code></td></tr></tbody></table><p><code>simd_kernels.cpp</code> 里的标量内核<strong>永远</strong>被编译进来：它既是尾部补齐者，也是没有 汇编被链接时的完整实现。没有内核的构建是受支持的配置，不是坏掉的构建——CMake 配置阶段会打印它选了哪条路径。</p><h2 id="如何验证" tabindex="-1">如何验证 <a class="header-anchor" href="#如何验证" aria-label="Permalink to &quot;如何验证&quot;">​</a></h2><p><code>verify/test_native_simd.cpp</code> 是回归套件，不需要 CMake、tgfx、mpv 或 taitank 即可编译。摘自 <code>verify/README.md</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SIMD_ASM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$REPO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/neoflux/src/native/asm/premultiply_rgba_x86_64.S&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_NATIVE_ASM_PREMULTIPLY_X86_64=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$V</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/test_native_simd.cpp&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$REPO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/neoflux/src/native/simd_kernels.cpp&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SIMD_ASM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/t11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/tmp/t11</span></span></code></pre></div><p>arm64 上改用 <code>-DNEOFLUX_NATIVE_ASM_PREMULTIPLY_AARCH64=1</code> 与 <code>premultiply_rgba_aarch64.S</code>。两者都省略时套件仍然能跑：汇编用例报 <code>SKIP</code>， 标量路径被完整覆盖。</p><table tabindex="0"><thead><tr><th>用例</th><th>类别</th><th>证明什么</th></tr></thead><tbody><tr><td>1</td><td>smoke</td><td>手挑像素与两种退化 alpha（<code>0</code> 把 RGB 清成零，<code>255</code> 必须精确恒等）</td></tr><tr><td>2</td><td>smoke</td><td>尾部长度 <code>0..40</code> 全覆盖，外加 alpha 0 与 alpha 255 扫描</td></tr><tr><td>3</td><td>stress</td><td>65536 个随机像素（256 KiB），每个缓冲区后面都带哨兵守卫字节</td></tr><tr><td>4</td><td>death</td><td>恶意参数（空指针、<code>SIZE_MAX</code>、短于一个组的数量）绝不崩溃；POSIX 上在 fork 出的子进程中跑</td></tr><tr><td>5</td><td>smoke</td><td>原地 <code>dst == src</code> 与非原地结果一致</td></tr><tr><td>6</td><td>oracle</td><td>裸 C ABI 内核与标量参考一致，且不写超出返回数量的任何字节</td></tr><tr><td>7</td><td>oracle</td><td>汇编与第二个用 SSE2 intrinsic 写的 oracle 一致</td></tr></tbody></table><p>每个缓冲区都带哨兵带，所以多走一个组的内核会响亮地失败，而不是悄悄越界涂写。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./native-tuning">平台原生调优层</a> —— 这些内核外圈的 platform 层： <code>DetectCpuFeatures()</code>、缓存拓扑、线程调度。</li><li><a href="./cross-platform">跨平台</a> —— 各平台翻译单元（以及这些 <code>.S</code>）在配置期如何 被选择。</li><li><a href="./testing">测试</a> —— 上面用到的 smoke / death / stress 三类。</li><li><code>neoflux/src/native/asm/README.md</code> —— 面向贡献者的版本，含易读性要求与符号 命名约定。</li></ul><hr><p><em>自第一个手写 SIMD 内核（SSE2 / NEON premultiply）起提供。</em></p>`,56)])])}const k=e(s,[["render",i]]);export{g as __pageData,k as default};
